@font-face { font-display: swap; font-family: "Roboto Slab"; font-style: normal; font-weight: 200; src: local("Roboto Slab Extra Light "), local("Roboto Slab-Extra Light"), url("{{assets}}/hugo-theme-gruvbox_demo/roboto-slab-latin-200.woff2") format("woff2"), url("{{assets}}/hugo-theme-gruvbox_demo/roboto-slab-latin-200.woff") format("woff"); }
@font-face { font-display: swap; font-family: "Roboto Slab"; font-style: normal; font-weight: 300; src: local("Roboto Slab Light "), local("Roboto Slab-Light"), url("{{assets}}/hugo-theme-gruvbox_demo/roboto-slab-latin-300.woff2") format("woff2"), url("{{assets}}/hugo-theme-gruvbox_demo/roboto-slab-latin-300.woff") format("woff"); }
@font-face { font-display: swap; font-family: "Roboto Slab"; font-style: normal; font-weight: 400; src: local("Roboto Slab Regular "), local("Roboto Slab-Regular"), url("{{assets}}/hugo-theme-gruvbox_demo/roboto-slab-latin-400.woff2") format("woff2"), url("{{assets}}/hugo-theme-gruvbox_demo/roboto-slab-latin-400.woff") format("woff"); }

layer.css:
[data-ryt="footer"] { color: rgb(102, 92, 84); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 2px dotted var(--ryt-header-bg); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: rgb(40, 40, 40); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.675; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(40, 40, 40); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.675; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.675; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.675; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(40, 40, 40); border-bottom: 1px solid var(--ryt-header-bg); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(40, 40, 40); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #458588 }
[data-ryt="credit"] a::after, [data-ryt="review"] a::after, [data-ryt="bio"] a::after { content: " ↗"; display: inline; color: var(--ryt-accent); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.675; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-accent) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #458588 }
